16	      body && typeof body === 'object' && 'user_id' in body
17	        ? body.user_id
18	        : undefined;
19	
20	    if (typeof requestedUserId !== 'string' || !requestedUserId.trim()) {
21	      throw new ApiError('BAD_REQUEST', 'Openfort user ID is required.');
22	    }
23	
24	    const session = await verifyOpenfortAccessToken(accessToken);
25	
26	    if (session.user.id !== requestedUserId) {
27	      throw new ApiError(
28	        'FORBIDDEN',
29	        'Openfort user mismatch for encryption session.'
30	      );
31	    }
32	
33	    const encryptionSession = await createOpenfortEncryptionSession();
34	
