() => {
  const meta = document.querySelector('meta[name="referrer"]');
  return {
    found: !!meta,
    content: meta?.getAttribute('content'),
    allMeta: Array.from(document.querySelectorAll('meta')).map(m => ({ name: m.getAttribute('name'), content: m.getAttribute('content'), httpEquiv: m.getAttribute('http-equiv') }))
  };
}

() => {
  // Find the openfort iframe and check its context
  const iframe = document.getElementById('openfort-iframe');

  // Also check all iframes in main document
  const allIframes = Array.from(document.querySelectorAll('iframe')).map(f => ({
    id: f.id,
    src: f.src?.slice(0, 80),
    referrerpolicy: f.getAttribute('referrerpolicy'),
    sandbox: f.getAttribute('sandbox'),
    style: f.getAttribute('style'),
  }));

  // Check if iframe is inside a shadow DOM or another iframe
  return {
    openfortIframe: iframe ? {
      src: iframe.src?.slice(0, 80),
      referrerpolicy: iframe.getAttribute('referrerpolicy'),
      sandbox: iframe.getAttribute('sandbox'),
      style: iframe.getAttribute('style'),
      parentTag: iframe.parentElement?.tagName,
      grandParentTag: iframe.parentElement?.parentElement?.tagName,
      inShadowDom: iframe.getRootNode() !== document,
    } : 'NOT FOUND',
    documentReferrerPolicy: document.referrerPolicy,
    metaReferrer: document.querySelector('meta[name="referrer"]')?.content,
    allIframesInDoc: allIframes,
  };
}

() => {
  return {
    documentReferrerPolicy: document.referrerPolicy,
    documentReferrer: document.referrer,
    location: window.location.href,
  };
}

() => {
  return {
    docRefPolicy: document.referrerPolicy,
    allPolicies: {
      document: document.referrerPolicy,
      // check raw meta
      meta: document.querySelector('meta[name="referrer"]')?.content ?? 'none found',
    },
    iframeSrc: document.getElementById('openfort-iframe')?.src,
  };
}

() => {
  const policy = document.referrerPolicy;
  return `type=${typeof policy}, value=${JSON.stringify(policy)}`;
}

