function OpenfortIframeFix() {
  useEffect(() => {
    // Patch must run synchronously BEFORE appendChild so referrerpolicy is present
    // when the browser reads it to initiate the iframe navigation. A MutationObserver
    // fires after appendChild (microtask) which is already too late — Chrome commits
    // the navigation's referrer policy at the appendChild call site.
    const original = Node.prototype.appendChild;
    Node.prototype.appendChild = function <T extends Node>(child: T): T {
      if (
        child instanceof HTMLIFrameElement &&
        child.id === 'openfort-iframe' &&
        !child.referrerPolicy
      ) {
        child.referrerPolicy = 'origin';
      }
      return original.call(this, child) as T;
    };
    return () => {
      Node.prototype.appendChild = original;
    };
  }, []);
  return null;
}

